// Etapa 1 — expandir: adicionar a coluna nova (opcional)
ALTER TABLE clientes ADD COLUMN telefone VARCHAR(20);

// Etapa 2 — migrar: copiar dados da coluna antiga para a nova
UPDATE clientes SET telefone = telefone_fixo;

// Etapa 3 — transição: código passa a ler/escrever a coluna nova
// (a coluna antiga continua existindo)

// Etapa 4 — contrair: remover a coluna antiga
// somente após confirmar que nenhum código a usa
ALTER TABLE clientes DROP COLUMN telefone_fixo;
